 if(stored){const s=stored.state;Object.assign(state,freshState(s.island,s.tool));for(const k of Object.keys(state))state[k]=s[k];meta=stored.meta;nodes=makeNodes();for(let i=0;i<3;i++){nodes[i].left=stored.nodes[i].left;nodes[i].regen=stored.nodes[i].regen;}for(const [e,k] of [[player,'player'],[gatherer,'gatherer'],[courier,'courier']]){Object.assign(e,actor(),stored[k]);e.mode=['gather','drop','get','deliver'].includes(e.mode)?e.mode:'gather';}Object.assign(mill,stored.mill);return;}
