 for(const p of upgrades){if(!p.show())continue;const near=dist(player,p)<.9;cyl(p.x,.17,p.z,2,.11,2,near?'#efc778':'#ddc597');cyl(p.x,.24,p.z,1.8,.04,1.8,near?'#fff0b3':'#f7e5bb');const paid=state.paid[p.id]||0;if(paid)for(let i=0;i<Math.floor(paid/p.cost()*12);i++){const a=i*TAU/12;box(p.x+Math.sin(a)*.86,.3,p.z+Math.cos(a)*.86,.15,.05,.15,'#4d9990',a);}}
 for(const [p,col] of [[c.drop,'#80b6a6'],[c.sell,'#deb66c'],[c.repair,'#e8a27a'],...(state.island===2?[[special,orderActive()?'#8bdde1':'#92b7b9']]:[])]){cyl(p.x,.18,p.z,2.1,.025,2.1,col);cyl(p.x,.197,p.z,1.82,.02,1.82,'#f0d6a1');}
 for(let i=0;i<Math.min(9,mill.raw);i++)item(c.mill.x-1,.3+1+i*.12,c.mill.z,false,0,.6);for(let i=0;i<Math.min(12,mill.parts);i++)item(c.mill.x+1.05,1.15+i*.16,c.mill.z,true,0,.62);if(mill.raw){const y=1.4+Math.sin(t*8)*.18;box(c.mill.x,y,c.mill.z-.12,.85,.17,.65,'#dce0bd');item(c.mill.x,1.3,c.mill.z,true,0,.6);}
