 if(state.island===2&&state.done){const m=c.monument;cyl(m.x,3.9,m.z,.8,.56,.8,'#ffeaa0',0,1);for(let i=0;i<2;i++){const a=t*.4+i*Math.PI;box(m.x+Math.sin(a)*1.8,3.94,m.z+Math.cos(a)*1.8,.2,.03,3.6,'#fff0b2',a,1);}}
 if(state.island===1&&state.done){const m=c.monument;for(let i=0;i<4;i++){const a=t+i*TAU/4;box(m.x+Math.sin(a)*.35,3.34,m.z+Math.cos(a)*.35,.13,.12,.7,'#eac56f',a);}}
 for(let i=0;i<22;i++){const a=i*.65,r=13.5+(i%3)*2.5;box(Math.sin(a)*r+Math.sin(t+i)*.25,-.38,Math.cos(a)*r,1.2,.018,.06,'#9ed3cf',a,.25);}
